action.code:
if (open_list.empty()) {
    return nullptr;
}

/* Find the node with the lowest f-value (g + h) */
auto it = std::min_element(open_list.begin(), open_list.end(),
    [](RouteModel::Node* a, RouteModel::Node* b) {
        return (a->g_value + a->h_value) < (b->g_value + b->h_value);
    });

/* Store the pointer to the node to return */
RouteModel::Node* lowest_f_node = *it;

/* Remove the node from the open list */
open_list.erase(it);

return lowest_f_node;

